using EqlTracker.Core;

public static class CombatInspectionTests
{
    public static void Register(Action<string, Action> test)
    {
        static void Check(bool value) { if (!value) throw new Exception("Combat inspection assertion failed"); }
        var start = new DateTime(2026, 10, 17, 12, 0, 0);
        CombatEvent Event(string id, string actor, string target, long damage, int second, string owner = "Player", bool activity = false) => new() { Id = id, Time = start.AddSeconds(second), Actor = actor, Target = target, Damage = damage, Owner = owner, ActivityOnly = activity, Kind = "Melee", Ability = "bashes", Outcome = "Hit" };
        CharacterProfile Profile() => new() { Character = "Hero", Meter = new() { Scope = "History", EncounterId = "fight", Actor = "Combined" }, PetIdentities = [new() { Name = "Petname", From = start }], GroupMembers = [new() { Name = "Ally", From = start.AddSeconds(2), Until = start.AddSeconds(8) }, new() { Name = "Allypet", IsPet = true, From = start }] };
        Encounter Fight() => new() { Id = "fight", Start = start, End = start.AddSeconds(10), Finished = true, Events = [Event("self", "Hero", "orc", 100, 0), Event("pet", "Petname", "orc", 200, 10, "Pet"), Event("ally", "Ally", "orc", 500, 5, "Group", true), Event("before", "Ally", "orc", 999, 1, "Group", true), Event("after", "Ally", "orc", 999, 9, "Group", true), Event("incoming", "orc", "Ally", 700, 6, "Incoming", true), Event("nearby", "Stranger", "orc", 999, 6, "Unknown"), Event("allypet", "Allypet", "orc", 50, 7, "Group", true)], PlayerDamage = 100, PetDamage = 200 };
        CombatInspectionSnapshot Build(Encounter f, CharacterProfile p, bool healing = false, AbilityOutcome[]? outcomes = null) { var d = DpsViews.Build([f], null, DateTime.MinValue, p.Meter); return CombatInspection.Build(d, healing ? HealingMetrics.Build([f], [], p.Healing.Filter()) : null, p, outcomes ?? [], new Dictionary<string, SpellReference>(), "test", healing, "retained log checked"); }
        test("Resist grammar separates Self and named pet without creating damage", () => { var own = AbilityOutcomeParser.Parse("an orc resisted your Cinder Bolt I!", start, "Hero", "own"); var pet = AbilityOutcomeParser.Parse("an orc resisted Petname's Air Elemental Attack!", start, "Hero", "pet"); Check(own?.Actor == "Hero" && own.Ability == "Cinder Bolt I" && pet?.Actor == "Petname"); var parser = new LogParser("Hero"); var line = parser.Parse("[Sat Oct 17 12:00:01 2026] an orc resisted your Cinder Bolt I!", "x")!; var engine = new CombatEngine(Profile()); engine.Process(line); Check(line.AbilityOutcome != null && line.Combat == null && engine.Current == null); });
        test("Chat and unsupported failures do not become full-resist evidence", () => { foreach (string text in new[] { "Bob tells General:1, 'an orc resisted your Spell!'", "Bob says, 'an orc resisted your Spell!'", "Your target is out of range, get closer!", "an orc resisted something" }) Check(AbilityOutcomeParser.Parse(text, start, "Hero", "x") == null); });
        test("Resist diagnostics never extend an existing fight", () => { var p = Profile(); var engine = new CombatEngine(p); var parser = new LogParser("Hero"); engine.Process(parser.Parse("[Sat Oct 17 12:00:00 2026] You bash an orc for 100 points of damage.", "hit")!); engine.Process(parser.Parse("[Sat Oct 17 12:00:20 2026] an orc resisted your Cinder Bolt I!", "resist")!); Check(engine.Current!.End == start && engine.Current.Damage == 100); });
        test("Group projection respects timed membership and excludes incoming and unrelated damage", () => { var s = Build(Fight(), Profile()); Check(s.Members.Single(m => m.Name == "Ally").Total == 500 && s.Members.Single(m => m.Name == "Allypet").Total == 50 && s.Members.All(m => m.Name != "Stranger")); Check(s.Members.Sum(m => m.Total ?? 0) == 850); });
        test("Group denominator and ability totals reconcile without changing personal totals", () => { var f = Fight(); var s = Build(f, Profile()); var ally = s.Members.Single(m => m.Name == "Ally"); Check(ally.Rate == 50 && ally.Abilities.Sum(a => a.Damage) == ally.Total && ally.Abilities.Sum(a => a.Dps) == ally.Rate && f.Damage == 300 && f.End == start.AddSeconds(10)); });
        test("Unknown group coverage is not a verified zero", () => { var f = Fight(); f.Events.Clear(); f.DetailAvailable = false; var s = Build(f, Profile()); Check(s.Members.All(m => m.Total == null) && s.Coverage.Contains("summary-only")); });
        test("Group target filters are separate from personal attribution", () => { var p = Profile(); p.Meter.Target = "ORC"; Check(Build(Fight(), p).Members.Single(m => m.Name == "Ally").Total == 500); p.Meter.Target = "other"; Check(Build(Fight(), p).Members.All(m => m.Total == null)); });
        test("Full-resist-only spells are inspectable with unknown expected reduction", () => { var p = Profile(); p.Meter.Kind = "Spell"; var s = Build(Fight(), p, outcomes: [new("r", start.AddSeconds(4), "Hero", "orc", "Cinder Bolt I", "Full resist", "raw")]); Check(s.Rows.Single().Ability == "Cinder Bolt I" && s.Abilities.Values.Single().Lines.Any(l => l.Label == "Full resists" && l.Value.StartsWith("1 recorded")) && s.Abilities.Values.Single().Lines.Any(l => l.Label == "Resistance amount" && l.Value.StartsWith("Unknown"))); });
        test("Critical filters cannot label all spell failures as critical", () => { var p = Profile(); p.Meter.Kind = "Spell"; p.Meter.CriticalOnly = true; Check(Build(Fight(), p, outcomes: [new("r", start.AddSeconds(4), "Hero", "orc", "Cinder Bolt I", "Full resist", "raw")]).Rows.Count == 0); });
        test("Healing Group includes observed members in both Done and Received perspectives", () => { var f = Fight(); f.Heals = [new() { Id = "h1", Time = start.AddSeconds(4), Healer = "Ally", Recipient = "Hero", Ability = "Heal", Effective = 300, RecipientOwner = "Player" }, new() { Id = "h2", Time = start.AddSeconds(5), Healer = "Stranger", Recipient = "Ally", Ability = "Heal", Effective = 200 }]; var p = Profile(); var s = Build(f, p, true); Check(s.Members.Single(m => m.Name == "Ally").Total == 300); p.Healing.Direction = "Received"; s = Build(f, p, true); Check(s.Members.Single(m => m.Name == "Ally").Total == 200 && s.Members.Single(m => m.Name == "Self").Total == 300); });
        test("All local peaks uses earliest flat high points and excludes zero valleys", () => { var peaks = CombatChart.FindLocalPeaks(start, 8, 1, [0, 5, 5, 0, 3, 0, 7, 7, 0], []); Check(peaks.Select(p => p.Index).SequenceEqual(new[] { 1, 4, 6 }) && peaks.Select(p => p.Dps).SequenceEqual(new[] { 5d, 3d, 7d })); });
        test("Local peaks handle empty, single-value, endpoint and tied series", () => { Check(CombatChart.FindLocalPeaks(start, 1, 1, [], []).Count == 0); Check(CombatChart.FindLocalPeaks(start, 1, 1, [0], [1]).Single().Actor == "Self"); Check(CombatChart.FindLocalPeaks(start, 2, 1, [3, 1, 3], []).Select(p => p.Index).SequenceEqual(new[] { 0, 2 })); });
        test("Chart elapsed labels retain hours across long sessions and multiple days", () => { Check(CombatChart.ElapsedLabel(59) == "00:59" && CombatChart.ElapsedLabel(3661) == "1:01:01" && CombatChart.ElapsedLabel(90061) == "25:01:01" && CombatChart.ElapsedLabel(-1) == "00:00"); });
        test("Missing historical chart details never become zero-valued cursor samples", () => { var f = Fight(); f.Events.Clear(); f.DetailAvailable = false; var chart = CombatChart.Build([f], new()); Check(!chart.DetailComplete && !chart.HasEvents && chart.Sample(4) == null); var known = chart with { DetailComplete = true }; Check(known.Sample(4) is { Self: 0, Pet: 0 }); });
        test("Chart local maxima leave existing sampled arrays and highest peaks unchanged", () => { var f = Fight(); var before = DpsViews.Build([f], null, DateTime.MinValue, Profile().Meter); var chart = before.Chart; Check(chart.LocalPeaks.All(p => (p.Actor == "Pet" ? chart.Pet : chart.Self)[p.Index] == p.Dps) && chart.Peaks.All(p => chart.LocalPeaks.Contains(p)) && before.Damage == 300); });
        test("Spell metadata preserves class levels, revision and contradictory base values", () => { var r = SpellReference.Parse("Spirit Tap", "{{Spellpagesmart|\n| description = Drains life, siphoning 210 hit points.\n| classes = * [[Necromancer]] - Level 26\n| slots = {{SpellSlotRow | 1 | Decrease Hitpoints by 132 (L29) to 150 (L35) }}\n| mana = 152\n}}", 42)!; Check(r.Classes.Contains("26") && r.Effects.Contains("150") && r.Revision == 42 && r.Limitation.StartsWith("Conflicting") && SpellReference.BaseName("Spirit Tap III") == "Spirit Tap"); });
        test("Non-spell wiki records cannot become spell references", () => Check(SpellReference.Parse("Sword", "{{Itempage}}", 1) == null));
        test("Outcome storage and independent checkpoint commit survive duplicate replay and restart", () => { var folder = Path.Combine(Path.GetTempPath(), "eql-outcomes-" + Guid.NewGuid()); Directory.CreateDirectory(folder); var path = Path.Combine(folder, "test.db"); try { var e = new AbilityOutcome("stable", DateTime.Now, "Hero", "orc", "Spell", "Full resist", "raw"); using (var store = new TrackerStore(path)) { store.SaveAbilityOutcomes([e, e], new() { Path = "log", Offset = 100, Generation = "file" }); store.SaveAbilityOutcomes([e]); } using (var store = new TrackerStore(path)) Check(store.LoadAbilityOutcomes().Single() == e && store.Get<FileCheckpoint>("abilityOutcomeCheckpoint")!.Offset == 100); } finally { Microsoft.Data.Sqlite.SqliteConnection.ClearAllPools(); Directory.Delete(folder, true); } });
        test("Old profiles default to Bright Frost and stable Damage navigation", () => { var p = System.Text.Json.JsonSerializer.Deserialize<CharacterProfile>("{}")!; Check(p.SecondaryText == "Bright Frost" && p.CombatLab.Mode == CombatLabMode.Damage && p.CombatLab.Peaks == ChartPeakMode.Highest); p.SecondaryText = "Warm Gold"; p.CombatLab.HealingTab = CombatLabTab.Group; var copy = EquipmentPositions.Copy(p); Check(copy.SecondaryText == "Warm Gold" && copy.CombatLab.HealingTab == CombatLabTab.Group); });
        test("Timeline cursor clamps to cached samples and keeps sampling denominators explicit", () => { var chart = new CombatChart(start, 4, 2, [10, 20, 30], [1, 2, 3], []); Check(chart.Sample(-20) == new TimelineCursor(start, 0, 1, 10, 2)); Check(chart.Sample(3) == new TimelineCursor(start.AddSeconds(2), 2, 2, 20, 2)); Check(chart.Sample(100) == new TimelineCursor(start.AddSeconds(4), 4, 3, 30, 2)); Check(chart.Sample(double.NaN) == null && new CombatChart(default, 1, 1, [], [], []).Sample(0) == null); });
        test("Cancelled inspection work cannot publish a partially computed result", () => { using var source = new CancellationTokenSource(); source.Cancel(); var p = Profile(); try { CombatInspection.Build(DpsViews.Build([Fight()], null, DateTime.MinValue, p.Meter), null, p, [], new Dictionary<string, SpellReference>(), "cancelled", false, "unknown", cancellation: source.Token); throw new Exception("Ignored cancellation"); } catch (OperationCanceledException) { } });
        test("Healing group filter choices include external named healers independently of personal actor filters", () => { var f = Fight(); f.Heals = [new() { Id = "external", Time = start.AddSeconds(4), Healer = "Externalcleric", Recipient = "Hero", RecipientOwner = "Player", Ability = "Heal", Effective = 100 }]; var p = Profile(); var snapshot = Build(f, p, true); Check(snapshot.Healers.Contains("Externalcleric") && snapshot.Recipients.Contains("Hero") && snapshot.Members.All(m => m.Name != "Externalcleric")); });
    }
}
